<script>
 import {onMount} from 'svelte';import {page} from '$app/stores';import {goto} from '$app/navigation';import {listDatabaseServers,listDatabases} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 let servers=[],databases=[],loading=true;
 async function load(){const projectId=$page.url.searchParams.get('project_id')||'';const environmentId=$page.url.searchParams.get('environment_id')||'';const [s,d]=await Promise.all([listDatabaseServers(projectId,environmentId),listDatabases(projectId,environmentId)]);if(s.ok)servers=s.data.servers||[];else notify(s.error||'Не удалось загрузить Database Servers','error');if(d.ok)databases=d.data.databases||[];else if(d.status!==0)notify(d.error||'Не удалось загрузить базы','error');loading=false}
 onMount(load);
 function scopedQuery(){const q=new URLSearchParams();const projectId=$page.url.searchParams.get('project_id');const environmentId=$page.url.searchParams.get('environment_id');if(projectId)q.set('project_id',projectId);if(environmentId)q.set('environment_id',environmentId);const query=q.toString();return query?'?'+query:''}
 function stateLabel(s){return ({planned:'Configuration saved',installing:'Installing',ready:'Ready',stopped:'Stopped',error:'Error'})[s]||s}
</script>
<svelte:head><title>Databases · VELTRIX Dock</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">INFRASTRUCTURE</div><h1 class="page-title">Databases</h1><p class="page-desc">Database Servers and independent databases across your Android devices.</p></div><div class="header-actions"><Button variant="secondary" on:click={()=>goto('/databases/new'+scopedQuery())}>＋ Create Database</Button><Button variant="primary" on:click={()=>goto('/databases/servers/new'+scopedQuery())}>＋ Add Database Server</Button></div></div>
{#if loading}<div class="empty">Загрузка инфраструктуры баз данных…</div>{:else}
<div class="section-header"><div><h2 class="section-title">Database Servers</h2><p class="section-desc">Локальные процессы СУБД на Android-устройствах.</p></div><span class="count">{servers.length} servers</span></div>
{#if servers.length}<div class="server-list">{#each servers as s}<article class="server-row" role="button" tabindex="0" on:click={()=>goto('/databases/servers/'+s.id+scopedQuery())}><span class="engine">{s.engine==='postgresql'?'PG':s.engine==='mariadb'?'M':'MY'}</span><div class="server-copy"><strong>{s.name}</strong><small>{s.engine} · {s.version||'Latest'} · Device #{s.device_id} · :{s.port}</small></div><span class="server-state"><StatusDot status={s.status==='ready'?'online':s.status==='error'?'error':'offline'}/>{stateLabel(s.status)}</span><span class="server-date">{new Date(s.created_at).toLocaleDateString()}</span></article>{/each}</div>{:else}<div class="empty compact"><strong>Database Servers ещё не добавлены</strong><p>Создайте конфигурацию сервера. Реальная установка будет активирована после реализации Agent lifecycle-команд.</p><Button variant="primary" on:click={()=>goto('/databases/servers/new'+scopedQuery())}>Настроить Database Server</Button></div>{/if}
<div class="section-header"><div><h2 class="section-title">Databases</h2><p class="section-desc">Отдельные базы внутри Database Server.</p></div><span class="count">{databases.length} databases</span></div>
{#if databases.length}<div class="server-list">{#each databases as d}<article class="server-row database-row" role="button" tabindex="0" on:click={()=>goto('/databases/'+d.id+scopedQuery())}><span class="engine small">DB</span><div class="server-copy"><strong>{d.name}</strong><small>{d.server_name} · {d.engine} · Device #{d.device_id}</small></div><span class="server-state">{d.status}</span></article>{/each}</div>{:else}<div class="empty compact">Базы появятся после установки и подключения Database Server.</div>{/if}
{/if}
<style>
.header-actions{display:flex;gap:8px;align-items:center}.eyebrow{font-size:9px;letter-spacing:.14em;color:#8AB4FF;font-weight:700;margin-bottom:7px}.section-header{display:flex;align-items:center;justify-content:space-between;margin:25px 0 11px}.section-title{font-size:12px}.section-desc,.count{font-size:9px;color:#64748b;margin-top:3px}.server-list{border:1px solid #253149;border-radius:11px;background:#101727;overflow:hidden}.server-row{display:flex;align-items:center;gap:11px;padding:12px;border-bottom:1px solid #1e293b}.server-row:last-child{border:0}.database-row{cursor:pointer}.database-row:hover{background:#172136}.engine{width:33px;height:33px;display:grid;place-items:center;border-radius:8px;background:#1e3a5f;color:#93c5fd;font-size:10px;font-weight:800;flex:none}.engine.small{background:#1A2638;color:#8AB4FF}.server-copy{display:grid;gap:3px;flex:1;min-width:0}.server-copy strong{font-size:11px}.server-copy small{font-size:9px;color:#64748b}.server-state{display:flex;align-items:center;gap:7px;font-size:9px;color:#94a3b8;white-space:nowrap}.server-date{font-size:9px;color:#64748b}.empty.compact{padding:24px}.empty.compact p{margin:7px 0 13px}
@media(max-width:600px){.header-actions{flex-direction:column;align-items:stretch}.server-date{display:none}.server-row{gap:8px}.server-state{font-size:8px}}
</style>